#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/channels/amp_bal.h>
// pydoc.h is automatically generated in the build directory
#include <amp_bal_pydoc.h>

void bind_amp_bal(py::module& m)
{

    using amp_bal = ::gr::channels::amp_bal;


    py::class_<amp_bal,
               gr::sync_block,
               gr::block,
               gr::basic_block,
               std::shared_ptr<amp_bal>>(m, "amp_bal", D(amp_bal))

        .def(py::init(&amp_bal::make), py::arg("alpha") = 1e-4, D(amp_bal, make))


        .def("alpha", &amp_bal::alpha, D(amp_bal, alpha))

        // name used by the former Python implementation
        .def("get_alpha", &amp_bal::alpha, D(amp_bal, alpha))


        .def("set_alpha", &amp_bal::set_alpha, py::arg("alpha"), D(amp_bal, set_alpha))

        ;
}
